    #[test]
    fn entity_type_catalog_is_complete_contiguous_and_unique() {
        assert_eq!(VANILLA_ENTITY_TYPES.len(), 157);
        let mut constant_names = HashSet::new();
        let mut resource_ids = HashSet::new();
        for (id, entry) in VANILLA_ENTITY_TYPES.iter().enumerate() {
            assert_eq!(entry.id, id as i32);
            assert!(constant_names.insert(entry.constant_name));
            assert!(resource_ids.insert(entry.resource_id));
            assert!(entry.resource_id.starts_with("minecraft:"));
        }
        assert_eq!(
            VANILLA_ENTITY_TYPES
                .iter()
                .filter(|entry| !entry.allowed_in_peaceful)
                .count(),
            37
        );
        assert_eq!(
            VANILLA_ENTITY_TYPES
                .iter()
                .filter(|entry| entry.mob_category == VanillaEntityMobCategory::Monster)
                .count(),
            44
        );
        assert_eq!(
            VANILLA_ENTITY_TYPES
                .iter()
                .filter(|entry| entry.only_op_can_set_nbt)
                .count(),
            3
        );
        assert_eq!(
            VANILLA_ENTITY_TYPES
                .iter()
                .filter(|entry| !entry.serializable)
                .count(),
            4
        );
        assert_eq!(
            VANILLA_ENTITY_TYPES
                .iter()
                .filter(|entry| !entry.can_summon)
                .count(),
            2
        );
        assert_eq!(
            VANILLA_ENTITY_TYPES
                .iter()
                .filter(|entry| entry.fire_immune)
                .count(),
            15
        );
        assert_eq!(
            VANILLA_ENTITY_TYPES
                .iter()
                .filter(|entry| !entry.track_deltas)
                .count(),
            10
        );
        assert_eq!(
            VANILLA_ENTITY_TYPES
                .iter()
                .filter(|entry| entry.eye_height.is_some())
                .count(),
            101
        );
        assert_eq!(
            VANILLA_ENTITY_TYPES
                .iter()
                .filter(|entry| entry.name_tag_offset.is_some())
                .count(),
            1
        );
        assert_eq!(
            VANILLA_ENTITY_TYPES
                .iter()
                .filter(|entry| entry.width >= 0.0 && entry.height >= 0.0)
                .count(),
            157
        );
        assert_eq!(
            VANILLA_ENTITY_TYPES
                .iter()
                .filter(|entry| !entry.passenger_attachments.is_empty())
                .count(),
            57
        );
        assert_eq!(
            VANILLA_ENTITY_TYPES
                .iter()
                .filter(|entry| entry.vehicle_attachment != [0.0; 3])
                .count(),
            24
        );
        assert_eq!(
            VANILLA_ENTITY_TYPES
                .iter()
                .filter(|entry| entry.in_arrows_tag)
                .count(),
            2
        );
        assert_eq!(
            VANILLA_ENTITY_TYPES
                .iter()
                .filter(|entry| entry.redirectable_projectile)
                .count(),
            3
        );
        assert_eq!(
            VANILLA_ENTITY_TYPES
                .iter()
                .filter(|entry| entry.deflects_projectiles)
                .count(),
            1
        );
        assert_eq!(
            VANILLA_ENTITY_TYPES
                .iter()
                .filter(|entry| entry.powder_snow_walkable)
                .count(),
            4
        );
        assert_eq!(
            VANILLA_ENTITY_TYPES
                .iter()
                .filter(|entry| entry.freeze_immune)
                .count(),
            4
        );
        assert_eq!(
            VANILLA_ENTITY_TYPES
                .iter()
                .filter(|entry| entry.non_controlling_rider)
                .count(),
            2
        );
        assert_eq!(
            VANILLA_ENTITY_TYPES
                .iter()
                .filter(|entry| entry.can_float_while_ridden)
                .count(),
            6
        );
        assert_eq!(
            VANILLA_ENTITY_TYPES
                .iter()
                .filter(|entry| entry.can_equip_saddle)
                .count(),
            11
        );
        assert_eq!(
            VANILLA_ENTITY_TYPES
                .iter()
                .filter(|entry| entry.can_wear_horse_armor)
                .count(),
            2
        );
        assert_eq!(
            VANILLA_ENTITY_TYPES
                .iter()
                .filter(|entry| entry.client_tracking_range == 10)
                .count(),
            74
        );
        assert_eq!(
            VANILLA_ENTITY_TYPES
                .iter()
                .filter(|entry| entry.client_tracking_range == 8)
                .count(),
            49
        );
        assert_eq!(
            VANILLA_ENTITY_TYPES
                .iter()
                .filter(|entry| entry.client_tracking_range == 4)
                .count(),
            23
        );
        assert_eq!(
            VANILLA_ENTITY_TYPES
                .iter()
                .filter(|entry| entry.client_tracking_range > 10)
                .count(),
            5
        );
        assert_eq!(
            VANILLA_ENTITY_TYPES
                .iter()
                .filter(|entry| entry.update_interval == 3)
                .count(),
            120
        );
        assert_eq!(
            VANILLA_ENTITY_TYPES
                .iter()
                .filter(|entry| entry.update_interval < 3)
                .count(),
            7
        );
        assert_eq!(
            VANILLA_ENTITY_TYPES
                .iter()
                .filter(|entry| entry.update_interval == i32::MAX)
                .count(),
            7
        );
        assert_eq!(
            VANILLA_ENTITY_TYPES
                .iter()
                .filter(|entry| entry.can_spawn_far_from_player)
                .count(),
            105
        );
        assert_eq!(
            VANILLA_ENTITY_TYPES
                .iter()
                .filter(|entry| entry.client_tracking_range >= 0 && entry.update_interval >= 1)
                .count(),
            157
        );
    }

